import{_ as a,o as i,c as t,a2 as e}from"./chunks/framework.Wk4ah3nE.js";const k=JSON.parse('{"title":"Installation","description":"Install Proxmox VM Autoscale with the installer script or by hand, including what the installer changes on your system and how to uninstall it.","frontmatter":{"title":"Installation","description":"Install Proxmox VM Autoscale with the installer script or by hand, including what the installer changes on your system and how to uninstall it.","head":[["link",{"rel":"canonical","href":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/guide/installation.html"}],["meta",{"property":"og:url","content":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/guide/installation.html"}],["meta",{"property":"og:title","content":"Installation"}],["meta",{"property":"og:description","content":"Install Proxmox VM Autoscale with the installer script or by hand, including what the installer changes on your system and how to uninstall it."}]]},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md","lastUpdated":null}'),n={name:"guide/installation.md"};function l(h,s,o,p,r,d){return i(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Two routes: the installer script, or a manual install. The manual route is longer but you see every change, which matters for a service that will hold root credentials.</p><h2 id="what-gets-installed" tabindex="-1">What gets installed <a class="header-anchor" href="#what-gets-installed" aria-label="Permalink to &quot;What gets installed&quot;">​</a></h2><p>Either way you end up with the same layout:</p><table tabindex="0"><thead><tr><th>Path</th><th>Contents</th><th>Mode</th></tr></thead><tbody><tr><td><code>/usr/local/bin/vm_autoscale/</code></td><td>Python sources, <code>config.yaml</code>, <code>logging_config.json</code></td><td><code>755</code></td></tr><tr><td><code>/usr/local/bin/vm_autoscale/config.yaml</code></td><td>Your hosts, VMs, credentials</td><td><strong><code>600</code>, root-owned</strong></td></tr><tr><td><code>/etc/vm_autoscale/config.yaml.backup</code></td><td>Copy of the previous config, kept across reinstalls</td><td><code>600</code> in <code>700</code> dir</td></tr><tr><td><code>/etc/systemd/system/vm_autoscale.service</code></td><td>systemd unit</td><td><code>644</code></td></tr><tr><td><code>/var/log/vm_autoscale.log</code></td><td>Service log</td><td>created on first run</td></tr></tbody></table><h2 id="option-a-—-installer-script" tabindex="-1">Option A — installer script <a class="header-anchor" href="#option-a-—-installer-script" aria-label="Permalink to &quot;Option A — installer script&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/fabriziosalmi/proxmox-vm-autoscale/main/install.sh)</span></span></code></pre></div><div class="danger custom-block"><p class="custom-block-title">You are piping a remote script into a root shell</p><p>This fetches whatever is on <code>main</code> at that moment and runs it as root, with no signature and no checksum. That is a real supply-chain exposure, not a theoretical one. If you would rather not, <a href="#reviewing-the-installer">download and read it first</a> or use the <a href="#option-b-manual-install">manual install</a>.</p></div><p>The script must run as root. It will:</p><ol><li>Create <code>/etc/vm_autoscale/</code> (mode <code>700</code>) and back up any existing <code>config.yaml</code> into it.</li><li><code>apt-get install</code> <code>python3</code>, <code>curl</code>, <code>bash</code>, <code>git</code>, <code>python3-paramiko</code>, <code>python3-yaml</code>, <code>python3-requests</code>, <code>python3-cryptography</code>.</li><li><strong>Delete</strong> <code>/usr/local/bin/vm_autoscale/</code> if it exists, then clone the repository into it.</li><li>Restore your backed-up <code>config.yaml</code> over the shipped example.</li><li><code>pip3 install -r requirements.txt</code>.</li><li>Set permissions — including locking <code>config.yaml</code> to mode <code>600</code>, because it holds your SSH password.</li><li>Write and <code>systemctl enable</code> the unit — <strong>without starting it</strong>.</li></ol><div class="warning custom-block"><p class="custom-block-title">Step 3 removes the install directory</p><p>Anything you put inside <code>/usr/local/bin/vm_autoscale/</code> that is not <code>config.yaml</code> — a custom webhook script, a patched module — is deleted on every reinstall. Keep such files elsewhere and reference them by absolute path.</p></div><h3 id="reviewing-the-installer" tabindex="-1">Reviewing the installer <a class="header-anchor" href="#reviewing-the-installer" aria-label="Permalink to &quot;Reviewing the installer&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/fabriziosalmi/proxmox-vm-autoscale/main/install.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">less</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span></span></code></pre></div><h3 id="if-pip3-install-fails" tabindex="-1">If <code>pip3 install</code> fails <a class="header-anchor" href="#if-pip3-install-fails" aria-label="Permalink to &quot;If \`pip3 install\` fails&quot;">​</a></h3><p>On Proxmox VE 8 and other Debian 12+ systems, pip refuses to install into the system Python:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error: externally-managed-environment</span></span></code></pre></div><p>The <code>apt-get</code> step above already installed <code>paramiko</code>, <code>PyYAML</code> and <code>requests</code> as system packages, so the service will run regardless — the pip step is redundant there. If you would rather have an isolated environment, use the <a href="#running-in-a-virtualenv">virtualenv variant</a> below.</p><h2 id="option-b-—-manual-install" tabindex="-1">Option B — manual install <a class="header-anchor" href="#option-b-—-manual-install" aria-label="Permalink to &quot;Option B — manual install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/fabriziosalmi/proxmox-vm-autoscale</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  /usr/local/bin/vm_autoscale</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/vm_autoscale</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Dependencies — system packages on Debian/Proxmox</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python3-paramiko</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python3-yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python3-requests</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Lock down the config before you put credentials in it</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chown</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root:root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config.yaml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 600</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config.yaml</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install the unit shipped in the repository</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vm_autoscale.service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/systemd/system/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon-reload</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vm_autoscale.service</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">The repository unit is the better one</p><p><code>vm_autoscale.service</code> in the repository sets <code>RestartSec=10</code> and a <code>Documentation=</code> link; the unit the installer generates inline does not. On a service configured to <code>Restart=always</code>, the missing <code>RestartSec</code> means a crash-looping process restarts as fast as systemd allows. Prefer the repository file.</p></div><h3 id="running-in-a-virtualenv" tabindex="-1">Running in a virtualenv <a class="header-anchor" href="#running-in-a-virtualenv" aria-label="Permalink to &quot;Running in a virtualenv&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/vm_autoscale/.venv</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/vm_autoscale/.venv/bin/pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  /usr/local/bin/vm_autoscale/requirements.txt</span></span></code></pre></div><p>Then point the unit at it:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># /etc/systemd/system/vm_autoscale.service.d/venv.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Service]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ExecStart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ExecStart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/usr/local/bin/vm_autoscale/.venv/bin/python /usr/local/bin/vm_autoscale/autoscale.py</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon-reload</span></span></code></pre></div><h2 id="configure-before-you-start" tabindex="-1">Configure before you start <a class="header-anchor" href="#configure-before-you-start" aria-label="Permalink to &quot;Configure before you start&quot;">​</a></h2><p>The service is enabled but <strong>not started</strong> after installation, on purpose. Edit the config first:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nano</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/vm_autoscale/config.yaml</span></span></code></pre></div><p>At minimum you need <code>proxmox_hosts</code> and <code>virtual_machines</code> filled in with real values. See <a href="/proxmox-vm-autoscale/guide/quick-start.html">your first scaling VM</a> for the smallest working example, and the <a href="/proxmox-vm-autoscale/reference/configuration.html">configuration reference</a> for every key.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vm_autoscale.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vm_autoscale.service</span></span></code></pre></div><h2 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h2><p>Re-running the installer preserves <code>config.yaml</code> through the backup/restore cycle. For a manual install:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/vm_autoscale</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/vm_autoscale/config.yaml.backup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vm_autoscale.service</span></span></code></pre></div><p>Read the <a href="/proxmox-vm-autoscale/reference/changelog.html">changelog</a> before upgrading — behaviour changes are listed there, including one that makes previously-ignored config values start taking effect.</p><h2 id="uninstalling" tabindex="-1">Uninstalling <a class="header-anchor" href="#uninstalling" aria-label="Permalink to &quot;Uninstalling&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vm_autoscale.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vm_autoscale.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/systemd/system/vm_autoscale.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon-reload</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/vm_autoscale</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/vm_autoscale</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # contains your config backup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  /var/log/vm_autoscale.log</span></span></code></pre></div><p>Uninstalling does <strong>not</strong> revert changes made to your VMs. Guests left with <code>hotplug</code> and <code>numa: 1</code> set by the autoscaler keep those settings, and cores and memory stay wherever the last scaling action left them. Check <code>qm config &lt;vmid&gt;</code> on anything that matters.</p>`,37)])])}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
